def get_Min_Squares(n):
    if n <= 3:
        return n;
    res = n 
    for x in range(1,n + 1):
        temp = x * x;
        if temp > n:
            break
        else:
            res = min(res,1 + get_Min_Squares(n  - temp)) 
    return res;

def max_sum_bi_tonic_sub_seq(arr):
    n = len(arr)
    dp = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        dp[i][i] = arr[i]
    for i in range(n-1):
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                dp[i][j] = max(dp[i][j], dp[i][j-1] + arr[j])
            else:
                dp[i][j] = max(dp[i][j], dp[i+1][j] + arr[i])
    return max(dp[0][-1], dp[-1][-1])

