def min_rotations(s1, s2):
    if len(s1)!= len(s2):
        return -1
    if s1 == s2:
        return 0
    if s1 == s2[::-1]:
        return 1
    if s1[0] == s2[0]:
        return min_rotations(s1[1:], s2[1:])
    if s1[0] == s2[-1]:
        return min_rotations(s1[1:], s2[:-1])
    if s1[-1] == s2[0]:
        return min_rotations(s1[:-1], s2[1:])
    if s1[-1] == s2[-1]:
        return min_rotations(s1[:-1], s2[:-1])
    return -1

