def odd_days_in_year(year):
    days = [1, 3, 5, 7, 8, 10, 12]
    odd_days = 0
    for month in range(1, 13):
        days_in_month = 28
        if month == 2:
            days_in_month = (year % 4 == 0 and year % 100!= 0) or year % 400 == 0 else 29
        for day in range(1, days_in_month + 1):
            if day in days:
                odd_days += 1
    return odd_days

