def max_profit(prices, k):
    if k == 0:
        return 0
    if k == 1:
        return max(prices) - min(prices)
    max_profit = 0
    for i in range(k):
        max_profit = max(max_profit, prices[i] - prices[i - 1])
    for i in range(k, len(prices)):
        max_profit = max(max_profit, prices[i] - prices[i - k])
    return max_profit

def find_first_occurrence(A, x):
    (left, right) = (0, len(A) - 1)
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if x == A[mid]:
            result = mid
            right = mid - 1
        elif x < A[mid]:
            right = mid - 1
        else:
            left = mid + 1
    return result

