def exponentiation(base, exponent):
    result = (1, 1)
    for i in range(len(exponent)):
        result = (result[0]*base[i], result[1]*base[i])
        if exponent[i] > 0:
            result = (result[0]*result[0], result[1]*result[1])
    return result

def remove_column(nested_list, column_index):
    """
    Remove a column from a nested list.

    :param nested_list: A nested list.
    :param column_index: The index of the column to remove.
    :return: A nested list with the specified column removed.
    """
    if not isinstance(nested_list, list):
        raise TypeError("nested_list must be a list")
    if not isinstance(column_index, int):
        raise TypeError("column_index must be an integer")
    if column_index < 0:
        raise ValueError("column_index must be greater than or equal to 0")
    if column_index >= len(nested_list):
        raise ValueError("column_index must be less than the length of nested_list")

    # Create a new nested list with the same number of rows as the original.
    new_nested_list = []
    for row in nested_list:
        # Create a new row with the same number of columns as the original.
        new_row = []
        for column in row:
            # If the column is not the column to remove, add it to the new row.
            if column_index!= column:
                new_row.append(column)
        new_nested_list.append(new_row)
    return new_nested_list

