def is_valid_triangle(p1, p2, p3):
    # Calculate the sides of the triangle
    a = (p2[0] - p1[0]) ** 2 + (p2[1] - p1[1]) ** 2
    b = (p3[0] - p1[0]) ** 2 + (p3[1] - p1[1]) ** 2
    c = (p3[0] - p2[0]) ** 2 + (p3[1] - p2[1]) ** 2

    # Check if the triangle has positive area
    if a > 0 and b > 0 and c > 0:
        return True
    else:
        return False

