def find_demlo_number(n):
    # Handle base case
    if n == 0:
        return 0

    # Calculate the square of the number
    square = n ** 2

    # Calculate the sum of the digits of the square
    sum_digits = sum(str(square))

    # Check if the sum of digits is a perfect square
    if sum_digits ** 2 == square:
        return n

    # If not, recursively call the function with the sum of digits
    else:
        return find_demlo_number(sum_digits)

