def exponentiation(a, b):
    """
    Exponentiation of two tuples.
    """
    if len(a)!= len(b):
        raise ValueError("Tuples must have the same length.")
    if len(a) == 0:
        return (1,)
    if len(b) == 0:
        return (1,)
    if len(a) == 1:
        return (a[0] ** b[0],)
    if len(b) == 1:
        return (a[0] ** b[0],)
    if a[0] == b[0]:
        return (a[0] ** b[0],) + exponentiation(a[1:], b[1:])
    else:
        return (a[0] ** b[0],) + exponentiation(a[1:], b[1:]) + (a[0] ** b[1],)

def pancake_sort(arr):
    stack = []
    for i in range(len(arr)):
        while stack and arr[stack[-1]] > arr[i]:
            pop = stack.pop()
        stack.append(i)
    return stack

