def count_most_common_words(words):
    """
    Count the most common words in a dictionary.

    :param words: A dictionary of words.
    :return: A dictionary of words and their counts.
    """
    word_counts = {}
    for word in words:
        if word not in word_counts:
            word_counts[word] = 1
        else:
            word_counts[word] += 1
    return sorted(word_counts.items(), key=lambda x: x[1], reverse=True)[:3]

def is_valid_triangle(a, b, c):
    # Calculate the sides and angles of the triangle
    side1 = sqrt((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2)
    side2 = sqrt((b[0] - c[0]) ** 2 + (b[1] - c[1]) ** 2)
    side3 = sqrt((c[0] - a[0]) ** 2 + (c[1] - a[1]) ** 2)
    ang1 = acos(dot(normalize(vector(a - b)), normalize(vector(b - c))) / (side1 * side2))
    ang2 = acos(dot(normalize(vector(b - a)), normalize(vector(c - a))) / (side2 * side3))
    ang3 = acos(dot(normalize(vector(c - b)), normalize(vector(a - b))) / (side3 * side1))

    # Check that all angles are within 180 degrees
    return abs(ang1) <= 180 and abs(ang2) <= 180 and abs(ang3) <= 180

