def inversions(tuples):
    """
    Returns a list of tuples of the form (a, b) where a and b are elements of tuples
    and a > b.
    """
    inversions = []
    for t in tuples:
        for i in range(len(t) - 1):
            if t[i] > t[i + 1]:
                inversions.append((t[i], t[i + 1]))
    return inversions

def first_missing_positive(numbers):
    n = len(numbers)
    for i in range(n):
        if numbers[i]!= i + 1:
            continue
        for j in range(i + 1, n):
            if numbers[j] == i + 1:
                numbers[i], numbers[j] = numbers[j], numbers[i]
                break
            elif numbers[j] < i + 1:
                numbers[j], numbers[n - 1] = numbers[n - 1], numbers[j]
                n -= 1
                break
    for i in range(n):
        if numbers[i]!= i + 1:
            return i + 1
    return n + 1

def pell(n):
    """
    Calculates the nth Pell number.

    The Pell sequence starts with 0, 1, and each subsequent number is defined as the sum of the two preceding numbers (e.g. 0, 1, 2, 5, 12, 29, ...).

    Args:
        n (int): The index of the Pell number to be calculated.

    Returns:
        int: The nth Pell number.
    """
    if n <= 1:
        return n
    else:
        return pell(n-1) + pell(n-2)

