def min_squares(n):
    # Base case: If n is 0, the minimum number of squares is 0
    if n == 0:
        return 0

    # Otherwise, find the square root of n and round up to the nearest integer
    square_root = int(n ** 0.5)
    squares = [i ** 2 for i in range(square_root + 1)]

    # Find the first square that is greater than or equal to n
    for square in squares:
        if square >= n:
            return squares.index(square) + 1

    # If no square is greater than or equal to n, return the last square
    return squares.index(squares[-1]) + 1

