def longest_subsequence(arr):
    if len(arr) == 0:
        return 0
    if len(arr) == 1:
        return 1

    max_length = 0

    for i in range(len(arr)):
        for j in range(i+1, len(arr)):
            if abs(arr[i] - arr[j]) == 1:
                max_length = max(max_length, longest_subsequence(arr[i:j+1]))

