def kth_element(arr, k):
    """
    :param arr: a list of integers
    :param k: an integer
    :return: the kth element in the list
    """
    if k == 0:
        return arr[0]
    if k == 1:
        return arr[1]
    if k == len(arr):
        return arr[-1]
    if k < len(arr) / 2:
        return kth_element(arr[:k], k)
    else:
        return kth_element(arr[k:], k - len(arr) / 2)

