def odd_occurrences(arr):
    # Create a dictionary to count the occurrences of each element
    count = {}
    for num in arr:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    # Initialize an empty list to store the elements with odd occurrences
    result = []

    # Iterate through the dictionary and append the elements with odd occurrences to the result list
    for num in count:
        if count[num] % 2!= 0:
            result.append(num)

    return result

def triplet_sum(arr):
    n = len(arr)
    for i in range(n-2):
        for j in range(i+1, n-1):
            for k in range(j+1, n):
                if arr[i] + arr[j] + arr[k] == 0:
                    return [arr[i], arr[j], arr[k]]
    return None

