def move_zeroes(arr):
    i = 0
    while i < len(arr):
        if arr[i]!= 0:
            j = i + 1
            while j < len(arr):
                if arr[j] == 0:
                    arr[i], arr[j] = arr[j], arr[i]
                j += 1
        i += 1

